function readinessRecord(caseNumber:1|2=1){return {kind:'copilot-mounted-history-readiness-v1' as const,caseNumber,journey:caseNumber===1?'follow' as const:'history-reading' as const,threadId:`native-thread-${caseNumber}`,attemptCount:1,outcome:'ready' as const,reason:'content-ready' as const,first:{status:'ready' as const,reason:'content-ready' as const,mountedRows:1,emptyRows:0,firstRowId:null,firstRowRole:null},last:{status:'ready' as const,reason:'content-ready' as const,mountedRows:1,emptyRows:0,firstRowId:null,firstRowRole:null},qualification:false as const};}
const pendingReadinessScalar=()=>({status:'pending',reason:'empty-text',mountedRows:1,emptyRows:1,firstRowId:'history-0',firstRowRole:'assistant'});
const exhaustedReadinessRecord=()=>({...readinessRecord(),attemptCount:120,outcome:'unavailable',reason:'attempt-limit',first:pendingReadinessScalar(),last:pendingReadinessScalar()});
test.each(['ready','invalid','unavailable'] as const)('readiness stdout writes nothing for impossible first-terminal %s then later record',async status=>{let writes=0;const port=tool.createRestoredHistoryDiagnosticPort((_b,done)=>{writes++;done();return true;});const first=status==='ready'?readinessRecord().first:{...pendingReadinessScalar(),status,reason:status==='invalid'?'selector':'node-cap',emptyRows:0};await expect(port.emitReadinessSummary({...exhaustedReadinessRecord(),first} as Parameters<typeof port.emitReadinessSummary>[0])).rejects.toThrow();expect(writes).toBe(0);});
