test.each(['deadline','source-error','admission-closed','public-active','public-history'] as const)('readiness stdout writes nothing for impossible post120th-pending %s',async reason=>{let writes=0;const port=tool.createRestoredHistoryDiagnosticPort((_b,done)=>{writes++;done();return true;});await expect(port.emitReadinessSummary({...exhaustedReadinessRecord(),outcome:reason==='public-history'?'invalid':'unavailable',reason} as Parameters<typeof port.emitReadinessSummary>[0])).rejects.toThrow();expect(writes).toBe(0);});
test('readiness stdout identity refusals isolate only the wrong-role or unknown-ID change',async()=>{const valid=exhaustedReadinessRecord();let writes=0;const good=tool.createRestoredHistoryDiagnosticPort((_b,done)=>{writes++;done();return true;});await good.emitReadinessSummary(valid as Parameters<typeof good.emitReadinessSummary>[0]);expect(writes).toBe(1);for(const change of [{firstRowRole:'user'},{firstRowId:'history-100'}]){let rejectedWrites=0;const port=tool.createRestoredHistoryDiagnosticPort((_b,done)=>{rejectedWrites++;done();return true;});const value={...valid,first:{...valid.first,...change},last:{...valid.last,...change}};await expect(port.emitReadinessSummary(value as Parameters<typeof port.emitReadinessSummary>[0])).rejects.toThrow();expect(rejectedWrites).toBe(0);}});
test('readiness stdout logger awaits original callback despite backpressure, with one compact LF line',async()=>{let callback!:(error?:Error|null)=>void;const writes:Uint8Array[]=[];const port=tool.createRestoredHistoryDiagnosticPort((bytes,cb)=>{writes.push(bytes);callback=cb;return false;});let done=false;const original=port.emitReadinessSummary(readinessRecord()).then(()=>{done=true;});await Promise.resolve();expect(done).toBe(false);expect(writes).toHaveLength(1);const text=Buffer.from(writes[0]!).toString();expect(text.endsWith('\n')).toBe(true);expect(text.split('\n')).toHaveLength(2);expect(Buffer.byteLength(text)).toBeLessThanOrEqual(4096);callback();await original;expect(done).toBe(true);});
test('readiness stdout logger charges attempted records even on sync throw and callback error',async()=>{const error=Error('sink');let writes=0;const port=tool.createRestoredHistoryDiagnosticPort(()=>{writes++;throw error;});await expect(port.emitReadinessSummary(readinessRecord())).rejects.toBe(error);await expect(port.emitReadinessSummary(readinessRecord())).rejects.toThrow();expect(writes).toBe(1);const cb=tool.createRestoredHistoryDiagnosticPort((_b,done)=>{done(error);return true;});await expect(cb.emitReadinessSummary(readinessRecord())).rejects.toBe(error);});
test('readiness stdout logger admits only each expected case once and no third record',async()=>{const writes:Uint8Array[]=[];const port=tool.createRestoredHistoryDiagnosticPort((b,cb)=>{writes.push(b);cb();return true;});await port.emitReadinessSummary(readinessRecord());await port.emitReadinessSummary(readinessRecord(2));await expect(port.emitReadinessSummary(readinessRecord(2))).rejects.toThrow();expect(writes).toHaveLength(2);});
test.each([['history-0','assistant'],['history-50','assistant'],['history-99','user']] as const)('readiness stdout uses exact fixed H100 catalog %s/%s',async(id,role)=>{let bytes=0;const port=tool.createRestoredHistoryDiagnosticPort((b,done)=>{bytes=b.byteLength;done();return true;});const r=readinessRecord();await port.emitReadinessSummary({...r,attemptCount:120,outcome:'unavailable',reason:'attempt-limit',first:{status:'pending',reason:'empty-text',mountedRows:100,emptyRows:100,firstRowId:id,firstRowRole:role},last:{status:'pending',reason:'empty-text',mountedRows:100,emptyRows:100,firstRowId:id,firstRowRole:role}});expect(bytes).toBeGreaterThan(0);expect(bytes).toBeLessThan(4096);});
