test.each(['extra-key','wrong-role','unknown-id','wrong-thread','wrong-journey','count','status','non-data'] as const)('readiness stdout refuses closed scalar/record contradiction %s before write',async kind=>{let writes=0;const port=tool.createRestoredHistoryDiagnosticPort((_b,cb)=>{writes++;cb();return true;});const r:unknown=readinessRecord();const value=r as Record<string,unknown>;if(kind==='extra-key')value.text='no';if(kind==='wrong-thread')value.threadId='native-thread-2';if(kind==='wrong-journey')value.journey='history-reading';if(kind==='count')value.attemptCount=0;if(kind==='status')value.outcome='pending';if(kind==='wrong-role'||kind==='unknown-id'){value.attemptCount=120;value.outcome='unavailable';value.reason='attempt-limit';value.first={status:'pending',reason:'empty-text',mountedRows:1,emptyRows:1,firstRowId:kind==='unknown-id'?'history-100':'history-0',firstRowRole:kind==='unknown-id'?'assistant':'user'};value.last=value.first;}if(kind==='non-data')Object.defineProperty(value,'threadId',{get(){throw Error('must not call getter');}});await expect(port.emitReadinessSummary(r as Parameters<typeof port.emitReadinessSummary>[0])).rejects.toThrow();expect(writes).toBe(0);});
