 let now=0,top=1400,geometry=0,pageRead=0,entryReads=0,completion:(event:TrackerACompletion)=>void=()=>{},sessionClose:(match:boolean)=>void=()=>{};
 const clock={now:()=>advancingClock?(now+=0.001):now,deadlineHostMs:120000,alarm:()=>()=>{},waitUntil:async(at:number)=>{now=Math.max(now,at);}};
 const trace=createMountedTrackerATrace({profileRef,clock,start:async()=>{},end:async()=>{completion({stream:'one',traceFormat:'json',streamCompression:'none',dataLossOccurred:false});},read:async()=>({data:'{}',eof:true}),closeIO:async()=>{},detach:async()=>{sessionClose(true);},installTracingComplete:cb=>{completion=cb;},removeTracingComplete:()=>{},installSessionClose:cb=>{sessionClose=cb;},removeSessionClose:()=>{},sink:{created:true,write:async()=>{},finish:async()=>rawRef,fsync:Promise.resolve(),fileClose:Promise.resolve()}});
 const record=(n:1|2)=>({caseNumber:n,journey:n===1?'follow' as const:'history-reading' as const,threadId:`thread-${n}`,seedRunId:`seed-${n}`,continuationRunId:`continue-${n}`,repetition:`rep-${n}`,completed:true,publicIdle:true,storeEmpty:true,domainReleased:true,originals:MOUNTED_CASE_WITNESS_LABELS.map(label=>({label,status:'fulfilled' as const}))});
 const scalar=()=>({pageNowMs:now+7000+(++pageRead)/1000,url:'http://localhost:1234/',sameOriginalScroller:true,connected:true,uniqueSelector:true,innerWidth:1280,innerHeight:800,devicePixelRatio:1,rect:{x:10,y:20,width:500,height:500},scrollTop:top,scrollHeight:2000,clientHeight:500});
