// These inspect fixed workflow SOURCE and supplied original ports; they do not
// execute GitHub expressions, a bootstrap CLI, SDK, browser or native process.
async function trackerWorkflowSource(){return readFile(new URL('../.github/workflows/hosted-copilot-tracker-a.yml',import.meta.url),'utf8').catch(error=>{if((error as NodeJS.ErrnoException).code==='ENOENT')return '';throw error;});}
function assertTrackerWorkflowBoundary(source:string){
 const blocks=source.split(/^      - name: /m).slice(1);
 const runtime=blocks.find(block=>block.includes('id: runtime\n'));
 const inventory=blocks.find(block=>block.includes('id: artifacts\n'));
 expect(runtime,'actual fixed runtime step').toBeDefined();
 expect(runtime).toContain('run: node --experimental-import-meta-resolve tools/hosted-copilot-mounted-bootstrap.mjs run\n');
 expect(runtime).not.toMatch(/^        if:/m);
 expect(inventory).toContain("if: always() && steps.runtime.outcome == 'success'\n");
 expect(inventory).toContain('run: node --experimental-import-meta-resolve tools/hosted-copilot-mounted-bootstrap.mjs inventory\n');
 expect(blocks.find(block=>block.includes('uses: actions/upload-artifact@'))).toContain("if: always() && steps.artifacts.outcome == 'success'\n");
 expect(source).not.toMatch(/continue-on-error|\|\||&&\s*(?:true|:)|set\s+\+e|exit\s+0|HOSTED_.*(?:ELIGIB|SUCCESS)/);
 const runs=blocks.filter(block=>block.includes('run: '));
 expect(runs.map(block=>block.match(/bootstrap\.mjs ([\w-]+)\n/)?.[1])).toEqual(['prepare','install','provision','run','inventory','failure-inventory']);
 for(const block of runs.slice(0,3))expect(block).not.toMatch(/^        if:/m);
 expect(source).toContain('run-name: hosted-copilot-react-tracker-json-a-v8\n');
}
test('fixed pilot SOURCE gates inventory on original runtime success and upload on inventory success',async()=>{assertTrackerWorkflowBoundary(await trackerWorkflowSource());});
