 for(const phase of ['fsync','close','authenticate'] as const)for(const rejected of [false,true]){
  const {value,retained}=await outerDiagnosticFixture(),gate=held<void>(),failure=Error(phase),writer=diagnosticWriter();let exit=0,visible:Uint8Array|null=null,closes=0,full:any;
  const publish=async(serial:unknown,path:'native-result.json'|'tracker-a-result.json')=>{const raw=Buffer.from(JSON.stringify(serial)+'\n');if(path!==name)return;full=serial;await tool.closeTrackerAPilotFile(raw,{write:async bytes=>{visible=bytes;},fsync:()=>phase==='fsync'?gate.promise:Promise.resolve(),close:()=>{closes++;return phase==='close'?gate.promise:Promise.resolve();}},async()=>{if(phase==='authenticate')await gate.promise;return {path,bytes:raw.length,sha256:createHash('sha256').update(raw).digest('hex')};});};
  const work=tool.runTrackerAPilotAction('run',()=>tool.publishTrackerAOuterResult(value,{writeNative:serial=>publish(serial,'native-result.json'),authenticateNative:async()=>({path:'native-result.json' as const,bytes:1,sha256:digest}),writeTracker:serial=>publish(serial,'tracker-a-result.json')},{retained,write:writer.write}),code=>{exit=code;});void work.catch(()=>{});
  for(let i=0;i<40;i++)await Promise.resolve();
  expect(visible).not.toBeNull();expect(JSON.parse(Buffer.from(visible!).toString('utf8'))).toEqual(full);expect(exit).toBe(1);
  // Genuine authenticated parent0 passes its own gate. It cannot establish
  // original closure of the later outer serial publication.
  const f=await publicationFiles(),command=completedCommand('parent'),parentRaw=Buffer.from(JSON.stringify(command)+'\n');f.files.set('parent-result.json',{raw:parentRaw,bytes:parentRaw.length,sha256:createHash('sha256').update(parentRaw).digest('hex')});
  await tool.admitTrackerAInventory(profileRef,{names:async()=>['parent-started.json',...f.files.keys()],read:f.read});expect(exit).toBe(1);
  if(rejected){gate.reject(failure);await expect(work).rejects.toBe(failure);expect(exit).toBe(1);}else{gate.resolve();await work;expect(exit).toBe(0);}expect(closes).toBe(1);
 }
